    if COMPILED_ANALYSIS_SHACL_DIR.is_dir():
        paths.extend(sorted(COMPILED_ANALYSIS_SHACL_DIR.glob("*.ttl")))
    if COMPILED_PROFILE_SHACL_ROOT.is_dir():
        paths.extend(sorted(COMPILED_PROFILE_SHACL_ROOT.glob("*/*.ttl")))
