def _safe_filename(field: str) -> str:
    """Convert `rkaf:hasArtifactIdentifier` → `has-artifact-identifier`."""
    s = re.sub(r"^[a-z]+:", "", field)
    s = re.sub(r"@", "", s)
    s = re.sub(r"([A-Z])", r"-\1", s).lower().lstrip("-")
    return re.sub(r"[^a-z0-9-]+", "-", s).strip("-")

