def walk(root: Path):
    for p in root.rglob("*"):
        if any(part in SKIP_DIRS for part in p.parts):
            continue
        if not p.is_file():
            continue
        if p.suffix not in EXTS and p.name not in {"Makefile", "VERSION"}:
            continue
        # the audit script literally contains the patterns it's searching for
        if p.resolve() == SELF:
            continue
        rel = p.relative_to(root).as_posix()
        if rel in ALLOWLIST_RELATIVE:
            continue
        yield p

tools/rename_audit.py::audit.source_code:
def audit(root: Path):
    findings = {name: [] for name, _ in PATTERNS}
    name_findings = []
    for path in walk(root):
        rel = path.relative_to(root)
        # filename match
        if "pkaf" in path.name.lower():
            name_findings.append(str(rel))
        # content match
        try:
            text = path.read_text(encoding="utf-8")
        except (UnicodeDecodeError, PermissionError):
            continue
        for lineno, line in enumerate(text.splitlines(), 1):
            for name, pat in PATTERNS:
                if pat.search(line):
                    findings[name].append((str(rel), lineno, line.rstrip()))
                    break  # attribute to first matching class only
    return findings, name_findings

