tools/rulespec_release.py::_record_index.source_code:
def _record_index(
    release: Mapping[str, Any],
    field: str,
    expected_type: str,
    issues: list[ValidationIssue],
) -> dict[str, Mapping[str, Any]]:
    records = release.get(field)
    result: dict[str, Mapping[str, Any]] = {}
    if not isinstance(records, list):
        _issue(issues, "MISSING_FIELD", f"$/{field}", "record array is required")
        return result
    for index, record in enumerate(records):
        path = f"$/{field}/{index}"
        if not isinstance(record, dict):
            _issue(issues, "INVALID_RECORD", path, "record must be an object")
            continue
        if record.get("record_type") != expected_type:
            _issue(
                issues,
                "WRONG_RECORD_TYPE",
                f"{path}/record_type",
                f"expected {expected_type}",
            )
            continue
        record_id = record.get("record_id")
        try:
            expected_id = stable_record_id(record)
        except ValueError as exc:
            _issue(issues, "MISSING_IDENTITY_FIELD", path, str(exc))
            continue
        if record_id != expected_id:
            _issue(
                issues,
                "RECORD_ID_MISMATCH",
                f"{path}/record_id",
                f"expected {expected_id}",
            )
        if not isinstance(record_id, str):
            continue
        if record_id in result:
            _issue(
                issues,
                "DUPLICATE_RECORD_ID",
                f"{path}/record_id",
                f"duplicate record {record_id}",
            )
            continue
        result[record_id] = record
    return result

