	"@type":      "rkaf:OrderDerived"
	"rkaf:fourth": string
	"rkaf:second": string & =~"^urn:"
}
"""
            )
            document = parse_cue_file(source)
            derived = next(
                shape
                for shape in document.shapes
                if shape.name == "OrderDerived"
            )
            self.assertEqual(
                [prop.name for prop in derived.properties],
                [
                    "rkaf:first",
                    "rkaf:second",
                    "rkaf:third",
