                [
                    "@type",
                    "rkaf:first",
                    "rkaf:second",
                    "rkaf:third",
                    "rkaf:fourth",
                ],
            )
            rust = target_rust(document)
            self.assertLess(
                rust.index("pub second:"), rust.index("pub third:")
            )
            self.assertLess(
                rust.index("pub third:"), rust.index("pub fourth:")
            )

