                "derived `?` un-required a base-required field",
            )

            shacl = target_shacl(document)
            self.assertRegex(
                shacl, r'sh:path rkaf:iri ;[^\n]*sh:pattern "\^urn:"'
            )
            self.assertRegex(
                shacl, r"sh:path rkaf:required ;[^\n]*sh:minCount 1"
            )

