        for match in re.finditer(
            r"^pub enum (\w+) \{\n(.*?)^\}", path.read_text(), re.M | re.S
        ):
            enums[match.group(1)] = tuple(
                re.findall(
                    r'#\[serde\(rename = "([^"]+)"\)\]', match.group(2)
                )
            )
    found: dict[str, tuple[str, ...] | None] = {}
    for path in sorted(self.GENERATED_RUST.rglob("*.rs")):
