            if annotation == "String":
                found[relative] = None
                continue
            self.assertIn(
                annotation,
                enums,
                f"generated Rust {relative} types {prop} as "
                f"{annotation}, which resolves to no generated enum.",
            )
            found[relative] = enums[annotation]
